"""Start Prompt. bin\\Prompt.exe is een kopie van pythonw.exe; door pyvenv.cfg in de Prompt-map
wordt die map de 'venv' en draait dit bestand automatisch bij het opstarten. Het laadt prompt.pyw
uit de Prompt-map en sluit daarna af, zodat er nooit een Python-prompt verschijnt."""
import os
import sys


def _start():
    app_dir = sys.prefix  # de Prompt-map (daar staat pyvenv.cfg; de exe staat in bin\)
    app = os.path.join(app_dir, "prompt.pyw")
    if not os.path.isfile(app):
        return
    # Alleen starten als Prompt.exe zonder script, -c of -m is aangeroepen (dan is sys.argv[0] leeg).
    if not sys.argv or sys.argv[0] != "":
        return
    argv = [a for a in sys.argv[1:] if a]
    opts = []
    xoptions = getattr(sys, "_xoptions", {})
    if "detach" in xoptions:
        opts.append("--detach")
    if "watch" in xoptions:  # opstarten met Windows: op de achtergrond wachten tot Claude opent
        opts.append("--watch")
    sys.argv = [sys.executable] + opts + argv
    import runpy
    code = 0
    try:
        runpy.run_path(app, run_name="__main__")
    except SystemExit as e:
        code = e.code if isinstance(e.code, int) else 0
    except Exception:
        try:
            import traceback
            with open(os.path.join(app_dir, "error.log"), "a", encoding="utf-8") as f:
                traceback.print_exc(file=f)
        except OSError:
            pass
        code = 1
    os._exit(code)


_start()
